//! Support for HOL boolean and conditional primitives, and the source list
//! representation.
//!
//! `HOL.bool` is represented by Rust's `bool`.  The source conditional
//! `HOL.If` is represented by `hol_if!`, which expands directly to Rust's
//! native `if` expression so that only the selected source branch is
//! evaluated and branch-local moves remain mutually exclusive.
//!
//! `List.list` is represented as an ordered `Vec<T>`.  `Nil` is the empty
//! vector and `Cons` prepends one element without deduplicating or reordering.

#[macro_export]
macro_rules! hol_if {
    ($condition:expr, $then_branch:expr, $else_branch:expr) => {
        if $condition {
            $then_branch
        } else {
            $else_branch
        }
    };
}

/// The source `List.list` datatype, represented as an ordered sequence.
///
/// Order and multiplicity, including duplicates, are preserved exactly.
/// This is not a set: no element is removed or deduplicated.
pub type List<T> = Vec<T>;

/// The source `List.list.Nil` constructor: the empty ordered sequence.
pub fn nil<T>() -> List<T> {
    Vec::new()
}

/// The source `List.list.Cons` constructor: prepend one element.
///
/// `cons(x, xs)` puts `x` before every element of `xs` and preserves all
/// elements and duplicates already present in `xs`.
pub fn cons<T>(x: T, xs: List<T>) -> List<T> {
    let mut result: List<T> = Vec::new();
    result.push(x);
    result.extend(xs);
    result
}

/// The source `Orderings.ord` class: overloaded ordering operations.
pub trait OrderingOrd {
    /// The source overloaded `<=` predicate; equal operands return `true`.
    fn less_eq(&self, other: &Self) -> bool;

    /// The source overloaded `<` predicate.
    fn less(&self, other: &Self) -> bool;
}

/// The source `Orderings.linorder` class: a total order extending `ord`.
pub trait Linorder: OrderingOrd {}

/// The source `InsertSort_Test.linorder_class.insort` function.
///
/// Source equations:
/// `insort x [] = [x]`
/// `insort x (y # ys) = if x <= y then x # y # ys else y # insort x ys`
pub fn insort<T: Linorder>(x: T, xs: List<T>) -> List<T> {
    let mut rest = xs.into_iter();
    match rest.next() {
        None => cons(x, nil()),
        Some(y) => {
            let ys: List<T> = rest.collect();
            if x.less_eq(&y) {
                cons(x, cons(y, ys))
            } else {
                let inserted_tail = insort(x, ys);
                cons(y, inserted_tail)
            }
        }
    }
}

/// The source `InsertSort_Test.linorder_class.isort` function.
///
/// Source equations:
/// `isort [] = []`
/// `isort (x # xs) = insort x (isort xs)`
pub fn isort<T: Linorder>(xs: List<T>) -> List<T> {
    let mut rest = xs.into_iter();
    match rest.next() {
        None => nil(),
        Some(x) => {
            let tail: List<T> = rest.collect();
            let sorted_tail = isort(tail);
            insort(x, sorted_tail)
        }
    }
}

