use i2r_candidate::{cons, hol_if, insort, isort, nil, Linorder, OrderingOrd};

#[derive(Debug)]
struct Keyed { key: u32, tag: u32 }

impl OrderingOrd for Keyed {
    fn less_eq(&self, other: &Self) -> bool {
        self.key <= other.key
    }

    fn less(&self, other: &Self) -> bool {
        self.key < other.key
    }
}

impl Linorder for Keyed {}

fn keys(xs: Vec<Keyed>) -> Vec<u32> {
    xs.into_iter().map(|x| x.key).collect()
}

fn pairs(xs: Vec<Keyed>) -> Vec<(u32, u32)> {
    xs.into_iter().map(|x| (x.key, x.tag)).collect()
}

#[test]
fn nil_is_empty_no_hidden_elements() {
    let got: Vec<Keyed> = nil();
    assert!(got.is_empty());
}

#[test]
fn cons_prepends_and_preserves_duplicates() {
    let got = cons(
        Keyed { key: 9, tag: 0 },
        vec![
            Keyed { key: 1, tag: 1 },
            Keyed { key: 1, tag: 2 },
        ],
    );
    assert_eq!(pairs(got), vec![(9, 0), (1, 1), (1, 2)]);
}

#[test]
fn keyed_less_eq_and_less_follow_total_linorder() {
    let one = Keyed { key: 1, tag: 10 };
    let two = Keyed { key: 2, tag: 20 };
    let two_again = Keyed { key: 2, tag: 21 };

    assert!(one.less_eq(&two));
    assert!(!two.less_eq(&one));
    assert!(two.less_eq(&two_again));

    assert!(one.less(&two));
    assert!(!two.less(&one));
    assert!(!two.less(&two_again));
}

#[test]
fn hol_if_selects_then_and_else_branches() {
    let t = hol_if!(true, 11u32, panic!());
    let f = hol_if!(false, panic!(), 22u32);
    assert_eq!(t, 11);
    assert_eq!(f, 22);

    let selected = hol_if!(
        true,
        vec![Keyed { key: 1, tag: 0 }],
        Vec::<Keyed>::new(),
    );
    assert_eq!(keys(selected), vec![1]);
}

#[test]
fn isort_empty_returns_empty() {
    let got = isort::<Keyed>(Vec::new());
    assert_eq!(keys(got), Vec::<u32>::new());
}

#[test]
fn isort_singleton_returns_singleton() {
    let got = isort(vec![Keyed { key: 7, tag: 1 }]);
    assert_eq!(keys(got), vec![7]);
}

#[test]
fn isort_reverse_sorts_ascending() {
    let got = isort(vec![
        Keyed { key: 5, tag: 50 },
        Keyed { key: 1, tag: 10 },
        Keyed { key: 4, tag: 40 },
        Keyed { key: 2, tag: 20 },
        Keyed { key: 3, tag: 30 },
    ]);
    assert_eq!(keys(got), vec![1, 2, 3, 4, 5]);
}

#[test]
fn isort_preserves_duplicates_and_multiplicity() {
    let got = isort(vec![
        Keyed { key: 2, tag: 20 },
        Keyed { key: 1, tag: 10 },
        Keyed { key: 2, tag: 21 },
        Keyed { key: 1, tag: 11 },
        Keyed { key: 2, tag: 22 },
    ]);
    assert_eq!(
        pairs(got),
        vec![(1, 10), (1, 11), (2, 20), (2, 21), (2, 22)]
    );
}

#[test]
fn isort_already_sorted_stays_sorted() {
    let got = isort(vec![
        Keyed { key: 1, tag: 10 },
        Keyed { key: 2, tag: 20 },
        Keyed { key: 2, tag: 21 },
        Keyed { key: 3, tag: 30 },
    ]);
    assert_eq!(pairs(got), vec![(1, 10), (2, 20), (2, 21), (3, 30)]);
}

#[test]
fn insort_empty_returns_singleton() {
    let got = insort(Keyed { key: 4, tag: 1 }, Vec::new());
    assert_eq!(keys(got), vec![4]);
}

#[test]
fn insort_less_equal_head_prepends() {
    let got = insort(
        Keyed { key: 2, tag: 9 },
        vec![
            Keyed { key: 2, tag: 8 },
            Keyed { key: 3, tag: 7 },
        ],
    );
    assert_eq!(pairs(got), vec![(2, 9), (2, 8), (3, 7)]);
}

#[test]
fn insort_greater_than_head_recurses() {
    let got = insort(
        Keyed { key: 5, tag: 50 },
        vec![
            Keyed { key: 1, tag: 10 },
            Keyed { key: 3, tag: 30 },
            Keyed { key: 4, tag: 40 },
        ],
    );
    assert_eq!(keys(got), vec![1, 3, 4, 5]);
}
